<script lang="ts">
import BookCover from './BookCover.svelte';
import {onMount,tick} from 'svelte';import {api,emptyDraft,type Draft,type Book,type Shelf} from '../../lib/api';import BookForm from './BookForm.svelte';
let deleted:Book|null=null;let restoreBusy=false;let restoreKey='';
let formBusy=false;let fetchedAt='';let cached=false;let isbn='';let busy=false;let error='';let warning='';let shelfError='';let draft:Draft|null=null;let reviewOpen=false;let shelves:Shelf[]=[];let input:HTMLInputElement;let review:HTMLElement;
onMount(()=>{input?.focus();loadShelves();const scanned=new URLSearchParams(window.location.search).get('isbn');if(scanned){isbn=scanned;lookup();}});
async function loadShelves(){shelfError='';try{shelves=await api<Shelf[]>('/api/shelves');}catch(e){shelfError='Shelves could not be loaded. You can save this copy as unassigned, or retry.';}}
async function lookup(e?:SubmitEvent){e?.preventDefault();if(busy||formBusy||restoreBusy)return;if(!isbn.trim()){error='Scan or type an ISBN first.';input?.focus();return;}busy=true;error='';deleted=null;draft=null;let focusReview=false;try{const v=await api<{existing?:Book;deleted?:Book;draft?:Draft;warning?:string;fetched_at?:string;cached?:boolean}>(`/api/isbn/${encodeURIComponent(isbn.trim())}`);if(v.deleted){deleted=v.deleted;restoreKey=crypto.randomUUID();}else if(v.existing){window.location.href=`/books/${v.existing.id}/`;}else{draft=v.draft||{...emptyDraft(),isbn:isbn.trim()};warning=v.warning||'';fetchedAt=v.fetched_at||'';cached=v.cached||false;reviewOpen=true;focusReview=true;}}catch(e){error=(e as Error).message;}finally{busy=false;await tick();if(focusReview){focusDetails()}else{input?.focus();input?.select()}}}
async function restore(){if(!deleted||restoreBusy)return;const restoring=deleted;restoreBusy=true;error='';try{await api(`/api/books/${restoring.id}/restore`,{revision:restoring.revision,expected_copy_count:restoring.total_copy_count,request_key:restoreKey});window.location.href=`/books/${restoring.id}/`;}catch(e){error=(e as Error).message;}finally{restoreBusy=false;}}
async function manual(){deleted=null;if(busy||formBusy||restoreBusy)return;fetchedAt='';cached=false;draft=emptyDraft();reviewOpen=true;warning='';error='';await tick();focusDetails();}
async function hideDetails(){reviewOpen=false;await tick();input?.focus();input?.select();}
async function resume(){reviewOpen=true;await tick();const target=review?.querySelector<HTMLElement>('input:not(:disabled), .library-notice a');target?.focus({preventScroll:true});review?.scrollIntoView({block:'start'});}
function focusDetails(){review?.querySelector('input')?.focus({preventScroll:true});review?.scrollIntoView({block:'start'});}
function saved(b:Book){window.location.href=`/books/${b.id}/`;}
</script>
<div class="scan_wrap"><form class="scan_input" onsubmit={lookup}><label class="library-field">Barcode or ISBN<input bind:this={input} bind:value={isbn} maxlength="64" placeholder="Scan here, then press Enter" autocomplete="off" inputmode="numeric" aria-describedby="scanner-help" disabled={busy||formBusy||restoreBusy}/></label><button class="library-button" disabled={busy||formBusy||restoreBusy}>{busy?'Looking up…':'Look up book'}</button></form><p id="scanner-help" class="library-help">Use a keyboard-style scanner with an Enter suffix. You can also type the ISBN.</p>{#if !draft}<button class="library-button secondary" onclick={manual} disabled={busy||formBusy||restoreBusy}>Add without an ISBN</button>{:else if !reviewOpen}<button class="library-button secondary" onclick={resume} disabled={busy||formBusy||restoreBusy}>Continue book details</button>{/if}
{#if deleted}<section class="library-notice" aria-label="Deleted book found"><h2>This book was deleted</h2><div class="scan_deleted-book"><BookCover title={deleted.title} coverUrl={deleted.cover_url} thumbnailUrl={deleted.cover_thumbnail_url}/><p>“{deleted.title}” has {deleted.total_copy_count} {deleted.total_copy_count===1?'copy':'copies'} saved. Restore its existing record to keep its shelf and loan history. Scanning has not added a copy.</p></div><button class="library-button" disabled={restoreBusy||busy} onclick={restore}>{restoreBusy?'Restoring…':'Restore book'}</button><a href="/settings/">Manage deleted books</a></section>{/if}
{#if error}<p class="library-error" role="alert">{error}</p>{/if}
{#if shelfError}<p class="library-notice" role="status">{shelfError} <button type="button" onclick={loadShelves}>Retry shelves</button></p>{/if}
{#if draft}<section class="scan_result" bind:this={review} hidden={!reviewOpen}><div class="library-actions"><h2>Check the book details</h2><button type="button" class="library-button secondary" disabled={busy||formBusy||restoreBusy} onclick={hideDetails}>Back to scanner</button></div>{#if warning}<p class="library-notice" role="status">{warning}</p>{:else if draft.source_url}<p class="library-help">Details from Open Library{fetchedAt ? ` · ${cached?'cached':'fetched'} ${new Date(fetchedAt).toLocaleDateString()}` : ''}. Check they match your edition.</p>{/if}{#key draft}<BookForm showCoverPreview {draft} {shelves} {saved} externalBusy={busy} busyChanged={(value)=>formBusy=value}/>{/key}</section>{/if}</div>
<style>@layer components {.scan_deleted-book{display:flex;align-items:center;gap:var(--space-3);margin-block:var(--space-3);p{min-width:0;overflow-wrap:anywhere}}.scan_wrap{display:grid;gap:var(--space-3);max-width:68rem}.scan_input{display:grid;grid-template-columns:1fr auto;gap:var(--space-3);align-items:end;@media(width<48rem){grid-template-columns:1fr}}.scan_result{scroll-margin-top:5rem;display:grid;gap:var(--space-4);border-top:var(--border-width) solid var(--border);padding-top:var(--space-5);margin-top:var(--space-4);h2{font-family:Georgia,serif;font-size:var(--h4)}&[hidden]{display:none}}}</style>
